  "extras": [
    {
      "after_item": "S13_METHOD",
      "title_raw": "나. 폐기시 주의사항",
      "reason": "코드없음",
      "statements": [
        {
          "key": "빈 용기 처리",
          "value": "환경관련 법규에 의거 처리 재생할 것."
        ,
        "line": "p13:L25"
        },
        {
          "key": "빈 용기 작업 주의",
          "value": "용접, 가열, 절단시 폭발하여 잔류물이 발화할 수도 있음."
        ,
        "line": "p13:L26"
        },
        {
          "key": "빈 용기 주의",
          "value": "압력을 주면 파열하는 경우가 있음."
        ,
        "line": "p13:L27"
        },
        {
          "key": "작업시 보호구",
          "value": "\"제8항\"에 의한 적절한 개인보호구를 착용할 것."
        ,
        "line": "p13:L28"
        },
        {
          "key": "주의사항",
          "value": "화기엄금, 흡입금지, 밀폐보관, 대기중 누출금지"
        ,
        "line": "p13:L29"
        },
        {
          "key": "겨울철 처리 주의",
          "value": "특히 겨울철 액체로 존재할 경우에도 소각처리 불가. 기화시켜 플레어스택에 유입하여 처리할"
        ,
        "line": "p13:L30"
        }
      ]
    ,
      "suggested_code": "S13_CAUTION_CONTENTS"
    ,
      "line": "p13:L24"
    }
  ]
}

